insert into invocations (id, name, name_en, grade, grade_order, spell_level, min_class_level, kind, saving_throw, spell_resistance, dice, scaling, description) values
  (gen_random_uuid(), 'Descarga sobrenatural', 'Eldritch Blast', 'Menor', 1, 1, 1, 'Ataque', 'Ninguna', 'Sí', '1d6', '1d6 a nivel 1 y +1d6 cada dos niveles de clase (3.º 2d6, 5.º 3d6… hasta 9d6 a nivel 17).', 'Rayo de energía que se lanza como un ataque de toque a distancia (alcance 60 pies). Es la aptitud básica del warlock: se usa a voluntad, sin límite diario. Las formas de descarga y las esencias sobrenaturales modifican esta descarga.')
insert into invocations (id, name, name_en, grade, grade_order, spell_level, min_class_level, kind, saving_throw, spell_resistance, dice, scaling, description) values
  (gen_random_uuid(), 'Palabra funesta', 'Baleful Utterance', 'Menor', 1, 2, 1, '—', 'Fortaleza niega (objeto)', 'Sí', '', '', 'Pronuncias una palabra del Habla Oscura y aplicas el efecto de «hacer añicos» sobre un objeto o criatura cristalina.')
insert into invocations (id, name, name_en, grade, grade_order, spell_level, min_class_level, kind, saving_throw, spell_resistance, dice, scaling, description) values
  (gen_random_uuid(), 'Influencia seductora', 'Beguiling Influence', 'Menor', 1, 2, 1, '—', 'Ninguna', 'No', '', 'Dura 24 horas.', 'Ganas un bono de +6 a las pruebas de Engañar, Diplomacia e Intimidar.')
insert into invocations (id, name, name_en, grade, grade_order, spell_level, min_class_level, kind, saving_throw, spell_resistance, dice, scaling, description) values
  (gen_random_uuid(), 'Suerte del Oscuro', 'Dark One''s Own Luck', 'Menor', 1, 2, 1, '—', 'Ninguna', 'No', '', 'Bono igual al modificador de Carisma; dura 24 horas.', 'Eliges Fortaleza, Reflejos o Voluntad: ganas un bono de suerte a esa salvación igual a tu modificador de Carisma.')
insert into invocations (id, name, name_en, grade, grade_order, spell_level, min_class_level, kind, saving_throw, spell_resistance, dice, scaling, description) values
  (gen_random_uuid(), 'Vista del diablo', 'Devil''s Sight', 'Menor', 1, 2, 1, '—', 'Ninguna', 'No', '', 'Alcance 30 pies; dura 24 horas.', 'Ves con normalidad en la oscuridad, incluida la oscuridad mágica.')
