-- =====================================================================
-- El grimorio completo: conjuros de clérigo y mago del SRD 3.5
-- (contenido abierto OGL, de d20srd.org) con toda la información de
-- juego: nivel por clase, atributo con el que escala la CD, escuela,
-- componentes, tiempo, alcance, objetivo, duración, salvación,
-- resistencia, dados y escalado.
--
-- Además, las invocaciones de warlock (Complete Arcane). El warlock NO
-- lanza conjuros: usa invocaciones a voluntad, por eso van en su propia
-- tabla con grado (menor/inferior/superior/oscura) en vez de nivel 0-9.
-- =====================================================================

-- ---- campos nuevos de la ficha del conjuro ------------------------
alter table spells add column if not exists name_en text not null default '';
alter table spells add column if not exists subschool text not null default '';
alter table spells add column if not exists descriptors text not null default '';
alter table spells add column if not exists components text not null default '';
alter table spells add column if not exists casting_time text not null default '';
alter table spells add column if not exists spell_range text not null default '';
alter table spells add column if not exists target text not null default '';
alter table spells add column if not exists target_kind text not null default '';
alter table spells add column if not exists duration text not null default '';
alter table spells add column if not exists saving_throw text not null default '';
alter table spells add column if not exists spell_resistance text not null default '';
alter table spells add column if not exists dice text not null default '';
alter table spells add column if not exists scaling text not null default '';
alter table spells add column if not exists cap text not null default '';
alter table spells add column if not exists description_en text not null default '';
alter table spells add column if not exists source text not null default 'SRD 3.5';

-- El atributo de lanzamiento es de la CLASE, no del conjuro:
--   CD del conjuro = 10 + nivel del conjuro + modificador del atributo.
alter table spell_classes add column if not exists key_ability text not null default '';

-- Los conjuros que ya estaban (V7) se completan en vez de duplicarse.
create unique index if not exists idx_spells_name on spells(name);

