-- ---- invocaciones de warlock (Complete Arcane) --------------------
-- El warlock no gasta espacios de conjuro: TODAS son a voluntad.
-- 'spell_level' es el nivel equivalente, solo para calcular la CD:
--   CD = 10 + spell_level + modificador de Carisma.
create table if not exists invocations (
    id              uuid primary key,
    name            text not null unique,
    name_en         text not null default '',
    grade           text not null,
    grade_order     int  not null,
    spell_level     int  not null,
    min_class_level int  not null,
    kind            text not null default '',
    saving_throw    text not null default '',
    spell_resistance text not null default '',
    dice            text not null default '',
    scaling         text not null default '',
    description     text not null default '',
    key_ability     text not null default 'Carisma',
    at_will         boolean not null default true,
    source          text not null default 'Complete Arcane'
);
create index if not exists idx_invocation_grade on invocations(grade_order, name);

